class Solution:
    def minWindow(self, s1: str, s2: str) -> str:
        best = ""
        i = 0
        while i < len(s1):
            j = 0
            while i < len(s1) and j < len(s2):
                if s1[i] == s2[j]:
                    j += 1
                i += 1
            if j < len(s2):
                break
            end = i
            j = len(s2) - 1
            i -= 1
            while j >= 0:
                if s1[i] == s2[j]:
                    j -= 1
                i -= 1
            i += 1
            if not best or end - i < len(best):
                best = s1[i:end]
            i += 1
        return best

